mapper.select:
SELECT AL.ACTIVITY_LOG_ID AS activityLogId, AL.TARGET_TYPE AS targetType, AL.TARGET_ID AS targetId, AL.ACTION_TYPE AS actionType, AL.ACTOR_USER_ID AS actorUserId, U.USER_NAME AS userName, AL.BEFORE_VALUE AS beforeValue, AL.AFTER_VALUE AS afterValue, TO_CHAR(AL.CREATED_AT, 'YYYY-MM-DD HH24:MI:SS') AS createdAt, AL.PROJECT_ID AS projectId FROM ACTIVITY_LOGS AL LEFT JOIN USERS U ON U.USER_ID = AL.ACTOR_USER_ID WHERE 1 = 1
AND AL.PROJECT_ID = #{projectId}
AND AL.ACTION_TYPE = #{activityType}
AND AL.TARGET_TYPE = #{targetType}
AND ( U.USER_NAME LIKE '%' || #{searchKeyword} || '%' OR AL.BEFORE_VALUE LIKE '%' || #{searchKeyword} || '%' OR AL.AFTER_VALUE LIKE '%' || #{searchKeyword} || '%' OR AL.TARGET_ID LIKE '%' || #{searchKeyword} || '%' )
AND AL.CREATED_AT >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
AND AL.CREATED_AT < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
ORDER BY AL.CREATED_AT ASC
ORDER BY AL.CREATED_AT DESC
